import { useState } from "react";
import { Button } from "@/registry/erbium/ui/button";
import {
  Drawer,
  DrawerTrigger,
  DrawerPanel,
  DrawerHeader,
  DrawerTitle,
  DrawerDescription,
  DrawerContent,
  DrawerFooter,
  DrawerClose,
} from "@/registry/erbium/ui/drawer";
import {
  Command,
  CommandInput,
  CommandList,
  CommandItem,
  CommandEmpty,
} from "@/registry/erbium/ui/command";
import { Slider } from "@/registry/erbium/ui/slider";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";

const projects = [
  "Design system",
  "Documentation",
  "Website",
  "Mobile app",
  "Research",
  "Product analytics",
  "Release planning",
  "Customer feedback",
  "Engineering tools",
  "Team workspace",
];

export default function SearchAndControlsExample() {
  const [selected, setSelected] = useState("Design system");
  const [zoom, setZoom] = useState(50);

  return (
    <Drawer showSwipeHandle>
      <DrawerTrigger render={<Button variant="outline" />}>Choose workspace project</DrawerTrigger>
      <DrawerPanel>
        <DrawerHeader>
          <DrawerTitle>Workspace projects</DrawerTitle>
          <DrawerDescription>Find a project and adjust its preview scale.</DrawerDescription>
        </DrawerHeader>
        <Command items={projects}>
          <CommandInput aria-label="Search projects" placeholder="Search projects…" />
          <CommandEmpty>No projects found.</CommandEmpty>
          <CommandList>
            {(project: string) => (
              <CommandItem
                key={project}
                value={project}
                onClick={() => {
                  setSelected(project);
                }}
              >
                {project}
              </CommandItem>
            )}
          </CommandList>
        </Command>
        <DrawerContent className="grid gap-group">
          <Field>
            <FieldLabel>Preview scale</FieldLabel>
            <Slider
              data-base-ui-swipe-ignore="x"
              value={zoom}
              onValueChange={(value) => {
                const [next] = [value].flat();

                if (next !== undefined) {
                  setZoom(next);
                }
              }}
              aria-label="Preview scale"
            />
          </Field>
          <output className="text-caption text-muted-foreground">
            {selected} · Preview scale {zoom}%
          </output>
        </DrawerContent>
        <DrawerFooter>
          <DrawerClose render={<Button />}>Done</DrawerClose>
        </DrawerFooter>
      </DrawerPanel>
    </Drawer>
  );
}

